-- 597: Original BrillaPrep Cambridge IGCSE Chemistry (0620) sprint 3 beta questions, part 4 of 13 (batch igcse-chemistry-sprint3-001).
-- Curriculum-aligned practice content; not official Cambridge International, WAEC or NSMQ examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_597_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_597_guard;
INSERT INTO _migration_597_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_013' AND NOT (q.topic_id IS 'topic_igcse_chem_bonding' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Graphite conducts electricity. Which feature of its structure explains this?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It contains freely moving ions.","B. Its layers are held together by strong covalent bonds.","C. It contains delocalised electrons that can move between the layers.","D. Each carbon atom forms only two covalent bonds."]' AND q.correct_answer IS 'C' AND q.explanation IS 'In graphite each carbon atom bonds to three others, leaving one delocalised electron per atom that can move along the layers and carry a current. (Graphite has no ions; the bonds within layers are covalent but the layers themselves attract weakly; each carbon forms three bonds, not two.) Therefore the correct answer is C: It contains delocalised electrons that can move between the layers..' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_013' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_597_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_014' AND NOT (q.topic_id IS 'topic_igcse_chem_bonding' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How many shared pairs of electrons are there in one molecule of methane, CH₄?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 1","B. 2","C. 8","D. 4"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The carbon atom shares one pair of electrons with each of the four hydrogen atoms, giving 4 shared pairs. (8 counts the individual shared electrons rather than the pairs; 2 would satisfy only two hydrogen atoms.) Therefore the correct answer is D: 4.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Determine' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_014' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_597_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_015' AND NOT (q.topic_id IS 'topic_igcse_chem_bonding' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Sodium reacts with chlorine to form sodium chloride, NaCl. Answer the following questions about the bonding and properties of sodium chloride.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) the sodium atom loses its outer electron to form Na⁺; (b) ionic bonding; (c) strong electrostatic attractions throughout the giant lattice need much energy to overcome.' AND q.explanation IS '(a) Sodium has the electron arrangement 2,8,1; losing the single outer electron leaves the stable arrangement 2,8 and the ion Na⁺. (b) The transfer of electrons from sodium to chlorine produces oppositely charged ions, so the bonding is ionic. (c) In the solid lattice every ion is surrounded by oppositely charged ions; the strong attractions extend in all directions, so a lot of heat energy is required to separate the ions, giving a high melting point.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '4' AND q.time_limit IS '300' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_015' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_597_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_igcse_chem_s3_016' AND NOT (q.topic_id IS 'topic_igcse_chem_stoichiometry' AND q.subject_id IS 'subj_igcse_chemistry' AND q.exam_type_id IS 'igcse' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the relative formula mass, Mr, of calcium carbonate, CaCO₃? (Ar: Ca = 40, C = 12, O = 16)' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 100","B. 68","C. 56","D. 96"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Mr = 40 + 12 + (3 × 16) = 40 + 12 + 48 = 100. (68 uses only one oxygen atom; 56 is the Mr of CaO; 96 doubles the oxygen contribution incorrectly.) Therefore the correct answer is A: 100.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_cambridge')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_igcse_chem_s3_016' AND NOT (r.batch_id IS 'igcse-chemistry-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Chemistry (0620) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-chemistry-0620/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_013', 'topic_igcse_chem_bonding', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Graphite conducts electricity. Which feature of its structure explains this?', 'multiple_choice', NULL, '["A. It contains freely moving ions.","B. Its layers are held together by strong covalent bonds.","C. It contains delocalised electrons that can move between the layers.","D. Each carbon atom forms only two covalent bonds."]', 'C', 'In graphite each carbon atom bonds to three others, leaving one delocalised electron per atom that can move along the layers and carry a current. (Graphite has no ions; the bonds within layers are covalent but the layers themselves attract weakly; each carbon forms three bonds, not two.) Therefore the correct answer is C: It contains delocalised electrons that can move between the layers..', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_014', 'topic_igcse_chem_bonding', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'How many shared pairs of electrons are there in one molecule of methane, CH₄?', 'multiple_choice', NULL, '["A. 1","B. 2","C. 8","D. 4"]', 'D', 'The carbon atom shares one pair of electrons with each of the four hydrogen atoms, giving 4 shared pairs. (8 counts the individual shared electrons rather than the pairs; 2 would satisfy only two hydrogen atoms.) Therefore the correct answer is D: 4.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Determine', 'AO2', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_015', 'topic_igcse_chem_bonding', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'Sodium reacts with chlorine to form sodium chloride, NaCl. Answer the following questions about the bonding and properties of sodium chloride.', 'structured', NULL, NULL, '(a) the sodium atom loses its outer electron to form Na⁺; (b) ionic bonding; (c) strong electrostatic attractions throughout the giant lattice need much energy to overcome.', '(a) Sodium has the electron arrangement 2,8,1; losing the single outer electron leaves the stable arrangement 2,8 and the ion Na⁺. (b) The transfer of electrons from sodium to chlorine produces oppositely charged ions, so the bonding is ionic. (c) In the solid lattice every ion is surrounded by oppositely charged ions; the strong attractions extend in all directions, so a lot of heat energy is required to separate the ions, giving a high melting point.', 'medium', '4', '4', '300', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igcse_chem_s3_016', 'topic_igcse_chem_stoichiometry', 'subj_igcse_chemistry', 'igcse', NULL, NULL, 'What is the relative formula mass, Mr, of calcium carbonate, CaCO₃? (Ar: Ca = 40, C = 12, O = 16)', 'multiple_choice', NULL, '["A. 100","B. 68","C. 56","D. 96"]', 'A', 'Mr = 40 + 12 + (3 × 16) = 40 + 12 + 48 = 100. (68 uses only one oxygen atom; 56 is the Mr of CaO; 96 doubles the oxygen contribution incorrectly.) Therefore the correct answer is A: 100.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge');
